import json
with open('transactions.json') as f:
    data = json.load(f)

transactions = {tx['id']: tx for tx in data['transactions']}
print('所有交易:', list(transactions.keys()))
print()
print('依赖关系:')
for tx in data['transactions']:
    if tx['dependency_ids']:
        print(f'{tx[\"id\"]} -> {tx[\"dependency_ids\"]}')

# 检查依赖环
print()
print('检查依赖环:')
def has_cycle(tx_id, visited, stack):
    visited.add(tx_id)
    stack.add(tx_id)

    for dep in transactions[tx_id]['dependency_ids']:
        if dep not in visited:
            if has_cycle(dep, visited, stack):
                return True
        elif dep in stack:
            return True

    stack.remove(tx_id)
    return False

visited = set()
cycles = []
for tx_id in transactions:
    if tx_id not in visited:
        stack = set()
        if has_cycle(tx_id, visited, stack):
            cycles.append(tx_id)

if cycles:
    print(f'发现依赖环涉及交易: {cycles}')
else:
    print('没有依赖环')
